using System;
using System.Collections.Generic;
using System.IO;
using System.Collections;
using System.Reflection;
using System.Globalization;
using UnityEditor.SceneManagement;
using UnityEngine;
using EasyRoads3Dv3;

// Reference facts only: every mesh and path sample is generated by the supplied EasyRoads runtime.
public static class UnityRoadContractProbe
{
    [Serializable] public class MeshRecord
    {
        public string name;
        public string[] materials;
        public Vector3[] positions;
        public int[] triangles;
    }
    [Serializable] public class Record
    {
        public string caseId;
        public string[] controls;
        public float[] strengths, tilting, tiltingCenters;
        public Vector3[] markers, centerline;
        public float distance;
        public float resolution, angleThreshold;
        public float createdResolution, createdAngleThreshold;
        public int createdSubSegments;
        public int subSegments;
        public int randomSeed;
        public bool terrainDeformationRequested;
        public float requestedTilting;
        public float minNodeDistance, faceDistance;
        public Vector3 initialDirection;
        public bool controlSetterReturned;
        public MeshRecord[] meshes;
        public string[] markerFacts;
    }
    [Serializable] public class Report
    {
        public string schema = "eve.tests.easyroads-path-contracts";
        public int schemaVersion = 1;
        public string axis = "Y-up; Unity Z reflected into EVEngine coordinates";
        public Record[] cases;
    }

    public static void Run()
    {
        string[] args = Environment.GetCommandLineArgs();
        int index = Array.IndexOf(args, "-roadContractOutput");
        if (index < 0 || index + 1 >= args.Length)
            throw new ArgumentException("-roadContractOutput OUTPUT_JSON is required");
        var records = new List<Record>();
        foreach (ERMarkerControlType control in Enum.GetValues(typeof(ERMarkerControlType)))
            records.Add(Generate("control-" + control, control, null, false, .5f));
        foreach (float strength in new float[] { 0f, .25f, .5f, 1f, 2f })
            records.Add(Generate("strength-" + strength.ToString(System.Globalization.CultureInfo.InvariantCulture),
                                 ERMarkerControlType.Spline, strength, false, .5f));
        records.Add(Generate("control-steep-circular", ERMarkerControlType.Circular, null, false, .5f));
        records.Add(Generate("control-mirror-circular", ERMarkerControlType.Circular, null, false, .5f));
        foreach(string variant in new string[] {"flat","flat-mirror","rising","rising-mirror","falling","falling-mirror"})
            records.Add(Generate("circular-height-"+variant,ERMarkerControlType.Circular,null,false,.5f));
        foreach(string variant in new string[] {"circular-zero-bump","circular-zero-bump-mirror",
            "circular-height-rising-zero-bump","circular-height-rising-mirror-zero-bump"})
            records.Add(Generate(variant,ERMarkerControlType.Circular,null,false,.5f));
        foreach(float scale in new float[] {.5f,2f})
            foreach(bool mirror in new bool[] {false,true})
                records.Add(Generate("circular-zero-bump-"+(mirror ? "mirror-" : "")+scale.ToString(CultureInfo.InvariantCulture),
                    ERMarkerControlType.Circular,null,false,.5f,geometryScale:scale));
        records.Add(Generate("control-angled-circular", ERMarkerControlType.Circular, null, false, .5f));
        records.Add(Generate("control-steep-straight", ERMarkerControlType.StraightXZ, null, false, .5f));
        records.Add(Generate("control-short-straight", ERMarkerControlType.StraightXZ, null, false, .5f));
        records.Add(Generate("default-spline", ERMarkerControlType.Spline, null, false, .5f));
        records.Add(Generate("variable-bank", ERMarkerControlType.Spline, null, true, .5f));
        records.Add(Generate("bank-pivot-left", ERMarkerControlType.Spline, null, true, 0f));
        records.Add(Generate("bank-pivot-right", ERMarkerControlType.Spline, null, true, 1f));
        records.Add(Generate("bank-pivot-varying", ERMarkerControlType.Spline, null, true, .5f));
        records.Add(Generate("sampling-resolution-1", ERMarkerControlType.Spline, null, false, .5f, 1f));
        records.Add(Generate("sampling-resolution-10", ERMarkerControlType.Spline, null, false, .5f, 10f));
        records.Add(Generate("sampling-angle-1", ERMarkerControlType.Spline, null, false, .5f, 10f, 1f));
        records.Add(Generate("sampling-angle-20", ERMarkerControlType.Spline, null, false, .5f, 10f, 20f));
        records.Add(Generate("sampling-transverse-3", ERMarkerControlType.Spline, null, false, .5f, 1f, 4f, 3));
        records.Add(Generate("sampling-fine-02", ERMarkerControlType.Spline, null, false, .5f, .2f, 4f));
        records.Add(Generate("sampling-angle-0", ERMarkerControlType.Spline, null, false, .5f, 10f, 0f));
        records.Add(Generate("sampling-unequal-20", ERMarkerControlType.Spline, null, false, .5f, 10f, 20f));
        records.Add(Generate("sampling-refresh-twice", ERMarkerControlType.Spline, null, false, .5f, 10f, 4f));
        records.Add(Generate("sampling-unequal-1", ERMarkerControlType.Spline, null, false, .5f, 10f, 1f));
        records.Add(Generate("sampling-width-4", ERMarkerControlType.Spline, null, false, .5f, 10f, 1f));
        records.Add(Generate("sampling-width-10", ERMarkerControlType.Spline, null, false, .5f, 10f, 1f));
        records.Add(Generate("sampling-scale-half", ERMarkerControlType.Spline, null, false, .5f, 10f, 1f));
        records.Add(Generate("sampling-scale-double", ERMarkerControlType.Spline, null, false, .5f, 10f, 1f));
        foreach(float scale in new float[] {.4f,.6f,.8f,1.2f,1.4f,1.6f,1.8f,2.2f})
            records.Add(Generate("sampling-scale-"+scale.ToString(CultureInfo.InvariantCulture),
                ERMarkerControlType.Spline,null,false,.5f,10f,1f,1,scale));
        foreach(float spacing in new float[] {.2f,1f,10f})
            records.Add(Generate("sampling-collinear-"+spacing.ToString(CultureInfo.InvariantCulture),
                ERMarkerControlType.Spline,null,false,.5f,spacing,1f));
        records.Add(Generate("sampling-seeded-a", ERMarkerControlType.Spline,null,false,.5f,10f,1f));
        records.Add(Generate("sampling-seeded-b", ERMarkerControlType.Spline,null,false,.5f,10f,1f));
        records.Add(Generate("sampling-seeded-other", ERMarkerControlType.Spline,null,false,.5f,10f,1f,1,1f,17));
        foreach(bool terrainMode in new bool[] {false,true})
            foreach(float tilt in new float[] {-360f,-45f,15f,30f,45f,180f,270f,360f})
                records.Add(Generate("tilt-"+(terrainMode ? "terrain-" : "free-")+tilt.ToString(CultureInfo.InvariantCulture),
                    ERMarkerControlType.Spline,null,true,.5f,terrainMode:terrainMode,tiltOverride:tilt));
        records.Add(Generate("tilt-free-varying-270",ERMarkerControlType.Spline,null,true,.5f,tiltOverride:270f));
        string output = Path.GetFullPath(args[index + 1]);
        Directory.CreateDirectory(Path.GetDirectoryName(output));
        File.WriteAllText(output, JsonUtility.ToJson(new Report { cases = records.ToArray() }, true));
        Debug.Log("ROAD_CONTRACT_PROBE_COMPLETE cases=" + records.Count);
    }

    private static Vector3 Native(Vector3 p) { return new Vector3(p.x, p.y, -p.z); }

    private static Record Generate(string name, ERMarkerControlType control, float? strength, bool bank, float pivot,
                                   float resolution=.375f, float angleThreshold=4f, int subSegments=1,float geometryScale=1f,
                                   int randomSeed=12345,bool terrainMode=false,float? tiltOverride=null)
    {
        UnityEngine.Random.State previousState = UnityEngine.Random.state;
        try
        {
            UnityEngine.Random.InitState(randomSeed);
            return GenerateCore(name,control,strength,bank,pivot,resolution,angleThreshold,subSegments,geometryScale,randomSeed,terrainMode,tiltOverride);
        }
        finally { UnityEngine.Random.state = previousState; }
    }

    private static Record GenerateCore(string name, ERMarkerControlType control, float? strength, bool bank, float pivot,
                                      float resolution, float angleThreshold, int subSegments,float geometryScale,
                                      int randomSeed,bool terrainMode,float? tiltOverride)
    {
        EditorSceneManager.NewScene(NewSceneSetup.EmptyScene, NewSceneMode.Single);
        var network = new ERRoadNetwork();
        Vector3[] markers = bank
            ? new Vector3[] { new Vector3(-18, 0, 0), Vector3.zero, new Vector3(18, 0, 0) }
            : new Vector3[] { new Vector3(-24, 0, 0), new Vector3(-8, 2, -8),
                              new Vector3(8, 5, -8), new Vector3(24, 1, 0) };
        if(name=="control-steep-circular") markers[3]=new Vector3(24,-20,0);
        if(name=="control-mirror-circular" || name.StartsWith("circular-zero-bump-mirror",StringComparison.Ordinal))
            for(int i=0;i<markers.Length;++i) markers[i].z=-markers[i].z;
        if(name.StartsWith("circular-height-",StringComparison.Ordinal)) {
            for(int i=0;i<markers.Length;++i) {
                markers[i].y=name.Contains("flat") ? 0f : name.Contains("rising") ? i*3f : -i*3f;
                if(name.Contains("-mirror")) markers[i].z=-markers[i].z;
            }
        }
        if(name=="control-angled-circular") markers[3]=new Vector3(24,1,-16);
        if(name=="control-steep-straight") markers[3]=new Vector3(24,-20,0);
        if(name=="control-short-straight") markers[2]=new Vector3(0,5,-8);
        if(name=="sampling-unequal-20" || name=="sampling-unequal-1") markers=new Vector3[] {
            new Vector3(-30,0,0),new Vector3(-7,3,-11),new Vector3(12,7,-8),new Vector3(31,1,4)};
        if(name.StartsWith("sampling-collinear-",StringComparison.Ordinal)) markers=new Vector3[] {
            new Vector3(-24,0,0),new Vector3(-8,0,0),new Vector3(8,0,0),new Vector3(24,0,0)};
        if(name=="sampling-scale-half" || name=="sampling-scale-double")
            for(int i=0;i<markers.Length;++i) markers[i]*=name=="sampling-scale-half" ? .5f : 2f;
        if(geometryScale!=1f)
            for(int i=0;i<markers.Length;++i) markers[i]*=geometryScale;
        ERRoad road = network.CreateRoad(name, new ERRoadType { roadTypeName = name,
            roadWidth = name=="sampling-width-4" ? 4f : name=="sampling-width-10" ? 10f : 6f }, markers);
        if (road == null) throw new InvalidDataException("Cannot create reference " + name);
        float createdResolution=road.GetResolution(),createdAngleThreshold=road.roadScript.angleTreshold;
        int createdSubSegments=road.roadScript.subSegments;
        road.SetTerrainDeformation(terrainMode);
        if(name.Contains("zero-bump")) road.SetRandomBumpiness(0f,0f,15f,35f);
        road.SetResolution(resolution);
        road.SetAngleThreshold(angleThreshold);
        road.roadScript.subSegments = subSegments;
        bool setterReturned = road.SetMarkerControlType(1, control);
        if (road.GetMarkerControlType(1) != control) throw new InvalidDataException("Control setter did not apply " + name);
        if (strength.HasValue) road.SetSplineStrength(1, strength.Value, false);
        if (bank)
        {
            float[] tilts = { -10f, 15f, -10f };
            for (int i = 0; i < markers.Length; ++i)
            {
                road.SetMarkerTiltingCenter(name=="bank-pivot-varying" ? (i==0 ? 0f : i==1 ? 1f : .5f) : pivot, i);
                road.SetMarkerTilting(name=="tilt-free-varying-270" && i!=1 ? 0f :
                    tiltOverride.HasValue ? tiltOverride.Value : tilts[i], i);
            }
        }
        Vector3 initialDirection=Native(road.roadScript.markersExt[0].direction);
        road.Refresh();
        if(name=="sampling-refresh-twice") road.Refresh();
        var facts = new List<string>();
        CollectFacts(road.roadScript, "road", facts, 0);
        var record = new Record {
            randomSeed=randomSeed,
            createdResolution=createdResolution,createdAngleThreshold=createdAngleThreshold,createdSubSegments=createdSubSegments,
            terrainDeformationRequested=terrainMode,requestedTilting=tiltOverride.HasValue ? tiltOverride.Value : 0f,
            initialDirection=initialDirection,minNodeDistance=road.roadScript.minNodeDistance,faceDistance=road.roadScript.faceDistance,
            resolution = road.GetResolution(), angleThreshold = road.roadScript.angleTreshold, subSegments=road.roadScript.subSegments,
            caseId = name, controls = new string[markers.Length], strengths = new float[markers.Length],
            tilting = new float[markers.Length], tiltingCenters = new float[markers.Length],
            markers = Array.ConvertAll(road.GetMarkerPositions(), Native), distance = road.GetDistance(),
            controlSetterReturned = setterReturned
        };
        record.markerFacts = facts.ToArray();
        for (int i = 0; i < markers.Length; ++i)
        {
            record.controls[i] = road.GetMarkerControlType(i).ToString();
            record.strengths[i] = road.GetSplineStrength(i);
            record.tilting[i] = road.GetMarkerTilting(i);
            record.tiltingCenters[i] = road.GetMarkerTiltingCenter(i);
        }
        var samples = new List<Vector3>();
        int cursor = 0;
        for (int i = 0; i <= 144; ++i)
            samples.Add(Native(road.GetPosition(record.distance * i / 144f, ref cursor)));
        record.centerline = samples.ToArray();
        var meshes = new List<MeshRecord>();
        foreach (MeshRenderer renderer in UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None))
        {
            MeshFilter filter = renderer.GetComponent<MeshFilter>();
            if (!renderer.enabled || !renderer.gameObject.activeInHierarchy || filter == null || filter.sharedMesh == null)
                continue;
            meshes.Add(new MeshRecord {
                name = renderer.name,
                materials = Array.ConvertAll(renderer.sharedMaterials, m => m == null ? "null" : m.name),
                positions = Array.ConvertAll(filter.sharedMesh.vertices, p => Native(renderer.transform.TransformPoint(p))),
                triangles = filter.sharedMesh.triangles
            });
        }
        if (meshes.Count == 0) throw new InvalidDataException("No reference mesh for " + name);
        record.meshes = meshes.ToArray();
        return record;
    }

    private static void CollectFacts(object value, string prefix, List<string> facts, int depth)
    {
        if (value == null || depth > 4 || facts.Count >= 1500) return;
        if (value is Vector3 point) { facts.Add(prefix + "=" + point.ToString("F9")); return; }
        if (value is IEnumerable nested && !(value is string))
        {
            int index = 0;
            foreach (object element in nested)
            {
                if (index == 8) break;
                CollectFacts(element, prefix + "/" + index, facts, depth + 1);
                ++index;
            }
            return;
        }
        foreach (FieldInfo field in value.GetType().GetFields(BindingFlags.Instance | BindingFlags.Public))
        {
            string name = field.Name.ToLowerInvariant();
            if (depth == 0) facts.Add(prefix + "/fieldType/" + field.Name + "=" + field.FieldType.FullName);
            object candidate = field.GetValue(value);
            if (candidate != null && field.FieldType.Namespace != null &&
                field.FieldType.Namespace.StartsWith("EasyRoads3Dv3") && !(candidate is UnityEngine.Object))
                CollectFacts(candidate, prefix + "/" + field.Name, facts, depth + 1);
            if (!(name.Contains("marker") || name.Contains("direction") || name.Contains("control") ||
                  name.Contains("spline") || name.Contains("circular") || name.Contains("position") || name.Contains("strength") ||
                  name.StartsWith("cp") || name.StartsWith("dp") || name == "pivotp" ||
                  (name.Length == 2 && name[0] == 'p' && char.IsDigit(name[1])) || name.EndsWith("circle") ||
                  name.Contains("random") || name == "tvalues" || name == "oldcp")) continue;
            object item = field.GetValue(value);
            string path = prefix + "/" + field.Name;
            if (item is Vector3 vector) facts.Add(path + "=" + vector.ToString("F9"));
            else if (item is float scalar) facts.Add(path + "=" + scalar.ToString("R", CultureInfo.InvariantCulture));
            else if (item is int || item is bool || (item != null && item.GetType().IsEnum)) facts.Add(path + "=" + item);
            else if (item is IEnumerable array)
            {
                int index = 0;
                foreach (object element in array)
                {
                    if (index == (name=="tvalues" ? 512 : 8)) break;
                    if (element is Vector3 position) facts.Add(path + "/" + index + "=" + position.ToString("F9"));
                    else if (element is float parameter) facts.Add(path + "/" + index + "=" + parameter.ToString("R", CultureInfo.InvariantCulture));
                    else CollectFacts(element, path + "/" + index, facts, depth + 1);
                    ++index;
                }
            }
        }
    }
}
